    seen = set()
    out = []
    for e in entries:
        k = e['id']
        if k not in seen:
            seen.add(k)
            out.append(e)
    return out

def project(entries):
    return [{'id': e['id'], 'label': e.get('label', ''), 'val': e.get('val', 0)} for e in entries]

